export function engineDecision(id,scenario){
 const managed=new Set(['the-house-of-the-dead-2','brutal-doom','brutal-doom-64','time-crisis-ii']);
 const result=(status,title,body,steps)=>({status,title,body,steps});
 if(scenario==='no-evidence')return result('BLOCKED / EXACT EVIDENCE','This package is not enabled','The launcher needs evidence for the exact package ID, version, digest and supported runtime. Installing an arbitrary latest engine does not resolve missing evidence.',['Use an up-to-date Momentum launcher.','A publisher must validate unknown package/build combinations.','Do not bypass approval.']);
 if(scenario==='host')return result('NEEDS ACTION / HOST','Complete the host prerequisites','Momentum does not elevate itself or install system prerequisites. Complete the documented host setup yourself, then start a fresh review.',['Preserve existing game files and software.','Review a new plan after host setup.']);
 if(scenario==='alternative'&&(id==='the-house-of-the-dead-2'||id==='virtua-cop-2'))return result('NOT AUTOMATIC / FLYCAST DISCOVERY','Do not assume an alternative is selected','The current launcher performs alternative-scope discovery for UZDoom and MAME, not Flycast. A supported Flycast copy elsewhere does not mean this selection path will discover it.',['The detected preferred copy still needs exact evidence.','HOD2 may offer its approved isolated fallback; Virtua Cop 2 has no registered fallback.','Preserve existing software and review the actual launcher plan.']);
 if(scenario==='supported'||scenario==='alternative')return result('REUSE / NO ENGINE CHANGE','Keep the supported runtime in place',scenario==='alternative'?'A supported alternative was found after the preferred copy failed the exact evidence match. Select the supported copy without changing either installation.':'The detected copy matches an explicitly supported build. Keep its provider, location and supported existing profile behavior.',['Do not move, upgrade or downgrade the existing engine.','Proceed to the game installation plan.','Existing game receipts do not silently switch engines.']);
 if(scenario==='missing'&&id==='time-crisis-ii')return result('PREPARE / ISOLATED MAME','Prepare the pinned isolated runtime','With the Flatpak client available and no existing game receipt, Time Crisis II can offer a build-specific isolated MAME installation even when no MAME copy exists. Both app and KDE runtime commits are pinned.',['Review separate software and game plans.','Existing-MAME lifecycle and synthetic acquisition flows passed; successful real network acquisition is not established.','Keep existing software and personal profiles untouched.']);
 if(scenario==='missing')return result('PREPARE / SEPARATE APPROVAL','Prepare missing user-scope software','With no conflicting installed copy, the ordinary approved preparation path obtains the exact supported build. It may stop if that build is no longer available.',['Review the concrete software plan.','Verify the exact engine identity after preparation.','Review the separate game installation plan.']);
 if(scenario==='unsupported'&&managed.has(id))return result('ISOLATED FALLBACK / SEPARATE APPROVAL','Offer a tested isolated runtime','For a new installation with host prerequisites met, this exact supported package can offer a verified managed Flatpak slot when no tested existing copy is available. Keep the current unsupported installation and personal profile untouched.',['Reuse a complete verified slot, or prepare it after approval.','Bind a separate per-game settings/save profile; existing receipts do not migrate automatically.','Review game changes afterward. Retain shared engine files on removal.']);
 return result('BLOCKED / UNTESTED BUILD','Preserve the untested installation','This package has no registered managed fallback in this guide. The installed version is not proven broken; its exact build is simply outside supported evidence.',['Do not replace the existing engine automatically.','Review supported builds or obtain updated evidence.']);
}
